mapper.select:
WITH rms AS MATERIALIZED (
SELECT DISTINCT ON (pp.played_at, pp.replay_id) pp.replay_id AS rid, pp.played_at AS date_add, m.battle_type, m.winner_wizard_id AS winner_wizard_id FROM public.rta_match_participant pp INNER JOIN public.rta_match m ON m.replay_id = pp.replay_id WHERE pp.season_id = #{seasonId} AND pp.rating_id = #{ratingId} ORDER BY pp.played_at DESC NULLS LAST, pp.replay_id DESC LIMIT #{limit} OFFSET #{offset}
SELECT DISTINCT ON (pp.played_at, pp.replay_id) pp.replay_id AS rid, pp.played_at AS date_add, m.battle_type, m.winner_wizard_id AS winner_wizard_id FROM public.rta_match_participant pp INNER JOIN public.rta_match m ON m.replay_id = pp.replay_id WHERE pp.season_id = #{seasonId} AND pp.rating_id IN #{rid} ORDER BY pp.played_at DESC NULLS LAST, pp.replay_id DESC LIMIT #{limit} OFFSET #{offset}
SELECT m.replay_id AS rid, m.played_at AS date_add, m.battle_type, m.winner_wizard_id AS winner_wizard_id FROM public.rta_match m WHERE 1 = 1
ORDER BY m.played_at DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}
), banned_pick AS ( SELECT ub.replay_id, ub.wizard_id AS wizard_id, MIN(ub.unit_master_id::text) AS banned_unit FROM public.rta_match_unit_pick ub INNER JOIN rms ON rms.rid = ub.replay_id WHERE ub.is_banned = true GROUP BY ub.replay_id, ub.wizard_id ), user_info AS ( SELECT p.replay_id, p.wizard_id AS wizard_id, p.wizard_name, p.channel_uid, p.country_code AS country, CAST(p.ladder_score AS text) AS score, CAST(p.rating_id AS text) AS rating, CASE WHEN p.is_winner THEN '1' ELSE '0' END AS result, CASE WHEN p.is_first_pick THEN '1' ELSE '0' END AS first_pick, p.alive_count, p.leader_pick_slot, bp.banned_unit FROM public.rta_match_participant p INNER JOIN rms ON rms.rid = p.replay_id LEFT JOIN banned_pick bp ON bp.replay_id = p.replay_id AND bp.wizard_id = p.wizard_id ), unit_info AS ( SELECT u.replay_id, u.wizard_id, array_agg(u.unit_master_id::text ORDER BY u.pick_slot_no) AS picked_units, array_agg( ORDER BY u.pick_slot_no) AS unit_images, array_agg(mo.kr_name ORDER BY u.pick_slot_no) AS unit_names, array_agg(u.is_banned ORDER BY u.pick_slot_no) AS unit_banned_flags, string_agg(u.unit_master_id::text, ',' ORDER BY u.pick_slot_no) AS picked_units_str FROM public.rta_match_unit_pick u LEFT JOIN public.monster mo ON mo.monster_id = u.unit_master_id::text INNER JOIN rms ON rms.rid = u.replay_id GROUP BY u.replay_id, u.wizard_id ), pair AS ( SELECT rms.rid, MIN(ui.wizard_id) AS p1w, MAX(ui.wizard_id) AS p2w FROM rms JOIN user_info ui ON ui.replay_id = rms.rid GROUP BY rms.rid ) SELECT rms.rid, rms.battle_type, rms.date_add, CASE WHEN rms.winner_wizard_id = pr.p1w THEN '1' ELSE '2' END AS winner_position, u1.wizard_id AS p1_wizard_id, u1.channel_uid AS p1_channel_uid, u1.wizard_name AS p1_name, u1.country AS p1_country, u1.score AS p1_score, u1.rating AS p1_rating, u1.result AS p1_result, u1.first_pick AS p1_first_pick, u1.alive_count AS p1_alive_count, u1.banned_unit AS p1_banned_unit, u1.leader_pick_slot AS p1_leader_unit, COALESCE(un1.picked_units, ARRAY[]::text[]) AS p1_units, COALESCE(un1.unit_images, ARRAY[]::text[]) AS p1_unit_images, COALESCE(un1.unit_names, ARRAY[]::text[]) AS p1_unit_names, COALESCE(un1.unit_banned_flags, ARRAY[]::boolean[]) AS p1_unit_banned, COALESCE(un1.picked_units_str, '') AS p1_units_str, u2.wizard_id AS p2_wizard_id, u2.channel_uid AS p2_channel_uid, u2.wizard_name AS p2_name, u2.country AS p2_country, u2.score AS p2_score, u2.rating AS p2_rating, u2.result AS p2_result, u2.first_pick AS p2_first_pick, u2.alive_count AS p2_alive_count, u2.banned_unit AS p2_banned_unit, u2.leader_pick_slot AS p2_leader_unit, COALESCE(un2.picked_units, ARRAY[]::text[]) AS p2_units, COALESCE(un2.unit_images, ARRAY[]::text[]) AS p2_unit_images, COALESCE(un2.unit_names, ARRAY[]::text[]) AS p2_unit_names, COALESCE(un2.unit_banned_flags, ARRAY[]::boolean[]) AS p2_unit_banned, COALESCE(un2.picked_units_str, '') AS p2_units_str FROM rms JOIN pair pr ON pr.rid = rms.rid JOIN user_info u1 ON u1.replay_id = rms.rid AND u1.wizard_id = pr.p1w JOIN user_info u2 ON u2.replay_id = rms.rid AND u2.wizard_id = pr.p2w LEFT JOIN unit_info un1 ON un1.replay_id = rms.rid AND un1.wizard_id = u1.wizard_id LEFT JOIN unit_info un2 ON un2.replay_id = rms.rid AND un2.wizard_id = u2.wizard_id ORDER BY rms.date_add DESC NULLS LAST

choose.when:
SELECT COUNT(DISTINCT pp.replay_id)::int
FROM public.rta_match_participant pp
WHERE pp.season_id = #{seasonId}
  AND DATE(pp.played_at AT TIME ZONE 'UTC') = CURRENT_DATE
  AND pp.rating_id = #{ratingId}

SELECT COUNT(DISTINCT pp.replay_id)::int
FROM public.rta_match_participant pp
WHERE pp.season_id = #{seasonId}
  AND DATE(pp.played_at AT TIME ZONE 'UTC') = CURRENT_DATE
  AND pp.rating_id IN
  #{rid}

SELECT COUNT(DISTINCT pp.replay_id)::int
FROM public.rta_match_participant pp
WHERE pp.season_id = #{seasonId}
  AND pp.played_at >= DATE_TRUNC('week', CURRENT_TIMESTAMP)
  AND pp.rating_id = #{ratingId}

SELECT COUNT(DISTINCT pp.replay_id)::int
FROM public.rta_match_participant pp
WHERE pp.season_id = #{seasonId}
  AND pp.played_at >= DATE_TRUNC('week', CURRENT_TIMESTAMP)
  AND pp.rating_id IN
  #{rid}

mapper.select:
SELECT COALESCE(SUM(t.total_matches)::bigint, 0::bigint)
FROM public.rta_agg_season_rating_match_total t
WHERE t.season_id = #{seasonId}

WITH match_total AS (
SELECT COALESCE(( SELECT t.total_matches::bigint FROM public.rta_agg_season_rating_match_total t WHERE t.season_id = #{seasonId} AND t.rating_id = #{ratingId} ), 0::bigint) AS total_matches
SELECT COALESCE(SUM(t.total_matches)::bigint, 0::bigint) AS total_matches FROM public.rta_agg_season_rating_match_total t WHERE t.season_id = #{seasonId} AND t.rating_id IN #{rid}
SELECT COALESCE(SUM(t.total_matches)::bigint, 0::bigint) AS total_matches FROM public.rta_agg_season_rating_match_total t WHERE t.season_id = #{seasonId}
), s AS (
SELECT sg.combo_unit_key, sg.pick_cnt, sg.match_cnt, sg.win_cnt, COALESCE(sg.ban_cnt, 0)::bigint AS ban_cnt FROM public.rta_agg_synergy_solo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id = #{ratingId}
SELECT sg.combo_unit_key, SUM(sg.pick_cnt)::bigint AS pick_cnt, SUM(sg.match_cnt)::bigint AS match_cnt, SUM(sg.win_cnt)::bigint AS win_cnt, SUM(COALESCE(sg.ban_cnt, 0))::bigint AS ban_cnt FROM public.rta_agg_synergy_solo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id IN #{rid} GROUP BY sg.combo_unit_key
SELECT sg.combo_unit_key, SUM(sg.pick_cnt)::bigint AS pick_cnt, SUM(sg.match_cnt)::bigint AS match_cnt, SUM(sg.win_cnt)::bigint AS win_cnt, SUM(COALESCE(sg.ban_cnt, 0))::bigint AS ban_cnt FROM public.rta_agg_synergy_solo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id > 0 GROUP BY sg.combo_unit_key
) SELECT s.combo_unit_key AS monster_id, m.monster_elemental AS monster_elemental, m.kr_name AS monster_name, AS monster_image, s.pick_cnt AS pick_count, ROUND((s.pick_cnt::numeric / NULLIF((SELECT mt.total_matches FROM match_total mt), 0) * 100)::numeric, 2) AS pick_rate, CASE WHEN s.match_cnt > 0 THEN ROUND((s.win_cnt::numeric / s.match_cnt * 100)::numeric, 2) ELSE 0 END AS win_rate, CASE WHEN s.pick_cnt > 0 THEN ROUND((s.ban_cnt::numeric / s.pick_cnt * 100)::numeric, 2) ELSE 0 END AS ban_rate FROM s LEFT JOIN public.monster m ON m.monster_id = s.combo_unit_key WHERE m.kr_name IS NOT NULL AND s.pick_cnt >= #{minPickCount} ORDER BY s.pick_cnt DESC LIMIT #{limit} OFFSET #{offset}

WITH s AS (
SELECT sg.combo_unit_key, sg.match_cnt, sg.win_cnt FROM public.rta_agg_synergy_duo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id = #{ratingId}
SELECT sg.combo_unit_key, SUM(sg.match_cnt)::bigint AS match_cnt, SUM(sg.win_cnt)::bigint AS win_cnt FROM public.rta_agg_synergy_duo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id IN #{rid} GROUP BY sg.combo_unit_key
SELECT sg.combo_unit_key, SUM(sg.match_cnt)::bigint AS match_cnt, SUM(sg.win_cnt)::bigint AS win_cnt FROM public.rta_agg_synergy_duo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id > 0 GROUP BY sg.combo_unit_key
) SELECT split_part(s.combo_unit_key, ',', 1) AS monster_id_1, split_part(s.combo_unit_key, ',', 2) AS monster_id_2, m1.kr_name AS monster_name_1, m2.kr_name AS monster_name_2, AS monster_image_1, AS monster_image_2, m1.monster_elemental AS monster_elemental_1, m2.monster_elemental AS monster_elemental_2, s.match_cnt AS match_count, ROUND((s.win_cnt::numeric / NULLIF(s.match_cnt, 0) * 100)::numeric, 2) AS win_rate FROM s LEFT JOIN public.monster m1 ON m1.monster_id = split_part(s.combo_unit_key, ',', 1) LEFT JOIN public.monster m2 ON m2.monster_id = split_part(s.combo_unit_key, ',', 2) WHERE m1.kr_name IS NOT NULL AND m2.kr_name IS NOT NULL AND s.match_cnt >= #{minPickCount} ORDER BY s.match_cnt DESC, (s.win_cnt::numeric / NULLIF(s.match_cnt, 0)) DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}

WITH s AS (
SELECT sg.combo_unit_key, sg.match_cnt, sg.win_cnt FROM public.rta_agg_synergy_trio sg WHERE sg.season_id = #{seasonId} AND sg.rating_id = #{ratingId}
SELECT sg.combo_unit_key, SUM(sg.match_cnt)::bigint AS match_cnt, SUM(sg.win_cnt)::bigint AS win_cnt FROM public.rta_agg_synergy_trio sg WHERE sg.season_id = #{seasonId} AND sg.rating_id IN #{rid} GROUP BY sg.combo_unit_key
SELECT sg.combo_unit_key, SUM(sg.match_cnt)::bigint AS match_cnt, SUM(sg.win_cnt)::bigint AS win_cnt FROM public.rta_agg_synergy_trio sg WHERE sg.season_id = #{seasonId} AND sg.rating_id > 0 GROUP BY sg.combo_unit_key
) SELECT split_part(s.combo_unit_key, ',', 1) AS monster_id_1, split_part(s.combo_unit_key, ',', 2) AS monster_id_2, split_part(s.combo_unit_key, ',', 3) AS monster_id_3, m1.kr_name AS monster_name_1, m2.kr_name AS monster_name_2, m3.kr_name AS monster_name_3, AS monster_image_1, AS monster_image_2, AS monster_image_3, m1.monster_elemental AS monster_elemental_1, m2.monster_elemental AS monster_elemental_2, m3.monster_elemental AS monster_elemental_3, s.match_cnt AS match_count, ROUND((s.win_cnt::numeric / NULLIF(s.match_cnt, 0) * 100)::numeric, 2) AS win_rate FROM s LEFT JOIN public.monster m1 ON m1.monster_id = split_part(s.combo_unit_key, ',', 1) LEFT JOIN public.monster m2 ON m2.monster_id = split_part(s.combo_unit_key, ',', 2) LEFT JOIN public.monster m3 ON m3.monster_id = split_part(s.combo_unit_key, ',', 3) WHERE m1.kr_name IS NOT NULL AND m2.kr_name IS NOT NULL AND m3.kr_name IS NOT NULL AND s.match_cnt >= #{minPickCount} ORDER BY s.match_cnt DESC, (s.win_cnt::numeric / NULLIF(s.match_cnt, 0)) DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}
